      try{ var m=JSON.parse(localStorage.getItem("jh-osc-place")||"{}"); return m&&typeof m==="object"?m:{}; }catch(e){ return {}; }
    }
    function oscPlace(id){ return oscPlaceMap()[id]==="chart"?"chart":"below"; }
